/**
 * Deterministic synthetic bytes for fixtures. Synthetic fixtures are generated by code;
 * they are never copied from RO clients, official sites or other repositories.
 */
export function syntheticBytes(seed: number, length: number): Uint8Array {
  const out = new Uint8Array(length);
  let x = seed >>> 0 || 0x9e3779b9;
  for (let i = 0; i < length; i += 1) {
    x ^= x << 13;
    x >>>= 0;
    x ^= x >>> 17;
    x ^= x << 5;
    x >>>= 0;
    out[i] = x & 0xff;
  }
  return out;
}

/** Bytes that start with a given ASCII magic followed by synthetic payload. */
export function withMagic(magic: string | Uint8Array, payloadLength: number, seed = 1): Uint8Array {
  const head = typeof magic === "string" ? new TextEncoder().encode(magic) : magic;
  const out = new Uint8Array(head.length + payloadLength);
  out.set(head, 0);
  out.set(syntheticBytes(seed, payloadLength), head.length);
  return out;
}
